contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        address sender = address(this);

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint recordedBeforeWithdraw = c.getBalance(sender); if (__ESBMC_reverted()) return;
        uint cBalanceBeforeWithdraw = address(c).balance;
        uint senderBalanceBeforeWithdraw = address(this).balance;

        bool withdrew;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        uint recordedAfter = c.getBalance(sender); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;

        assert(
            (withdrew && recordedAfter == 0 && cBalanceAfter == cBalanceBeforeWithdraw - recordedBeforeWithdraw && senderBalanceAfter == senderBalanceBeforeWithdraw + recordedBeforeWithdraw) ||
            (!withdrew && recordedAfter == recordedBeforeWithdraw && cBalanceAfter == cBalanceBeforeWithdraw && senderBalanceAfter == senderBalanceBeforeWithdraw)
        );
    }

    receive() external payable {}
}

