// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        address sender = address(this);
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 recordedBeforeWithdraw;
        try c.getBalance(sender) returns (uint256 __r) { recordedBeforeWithdraw = __r; } catch { return; }
        uint cBalanceBeforeWithdraw = address(c).balance;
        uint senderBalanceBeforeWithdraw = address(this).balance;
        bool withdrew;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 recordedAfter;
        try c.getBalance(sender) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;
        assertTrue((withdrew && recordedAfter == 0 && cBalanceAfter == cBalanceBeforeWithdraw - recordedBeforeWithdraw && senderBalanceAfter == senderBalanceBeforeWithdraw + recordedBeforeWithdraw) ||
            (!withdrew && recordedAfter == recordedBeforeWithdraw && cBalanceAfter == cBalanceBeforeWithdraw && senderBalanceAfter == senderBalanceBeforeWithdraw));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
